E=[]
def add(id,name,system,anchor,snv='',cnv='',rearr='',other='',pitfall='',refs='',aliases=''):
    split=lambda x: x.split('|') if x else []
    tax='cns' if system=='CNS' else 'eye' if system=='Eye and orbit' else 'soft'
    E.append(dict(id='nm-'+id,name=name,system=system,aliases=split(aliases),anchor=anchor,snv=split(snv),cnv=split(cnv),rearr=split(rearr),other=split(other),pitfall=pitfall,refs=['nm_'+r for r in [tax]+split(refs)]))

add('astro','Astrocytoma, IDH-mutant','CNS','IDH + TP53/ATRX; no whole-arm 1p/19q codeletion.','Defining — IDH1 R132 or IDH2 R172 mutation|Cooperating — TP53 and ATRX loss-of-function mutations','Grading — CDKN2A/B homozygous deletion establishes CNS WHO grade 4',pitfall='Grades 2–4 are one tumor type; an IDH-mutant grade 4 astrocytoma is not called glioblastoma.',refs='lgg|cns_summary')
add('oligo','Oligodendroglioma, IDH-mutant and 1p/19q-codeleted','CNS','Oligo = IDH + whole-arm 1p/19q loss.','Defining — IDH1 or IDH2 mutation|Cooperating — TERT promoter, CIC and FUBP1 mutations','Defining — Combined whole-arm 1p and 19q deletion',pitfall='Both IDH mutation and whole-arm codeletion are required; isolated/partial deletions do not qualify.',refs='lgg',aliases='Oligodendroglioma')
add('gbm','Glioblastoma, IDH-wildtype','CNS','EGFR, TERT, or +7/−10 in the appropriate adult diffuse glioma.','Driver — TERT promoter and EGFR mutations (subsets)|Cooperating — PTEN, NF1, TP53 and PI3K-pathway mutations','Driver — EGFR amplification|Characteristic — Whole chromosome 7 gain with chromosome 10 loss|Cooperating — CDKN2A/B deletion; PDGFRA or CDK4 amplification (subsets)','Driver — EGFR intragenic rearrangements such as EGFRvIII; FGFR3::TACC3 (small subset)',other='Predictive biomarker — MGMT promoter methylation is epigenetic, not a defining driver.',pitfall='Molecular diagnostic criteria require appropriate age, site and diffuse astrocytic context; exclude pediatric-type and other molecular gliomas.',refs='gbm|cns_summary',aliases='GBM')
add('dmg','Diffuse midline glioma, H3 K27-altered','CNS','Midline + loss of H3K27 methylation.','Defining — H3-3A/H3F3A or H3C-family K27M mutation (major subset)|Driver — EGFR mutation in an alternative molecular subset|Cooperating — ACVR1, TP53, PPM1D or PI3K-pathway mutations (subsets)',other='Defining — EZHIP overexpression can produce H3K27me3 loss without an H3 mutation.',pitfall='K27M alone outside a diffuse midline glioma does not establish this diagnosis. Histone legacy numbering is used.',refs='dmg|cns_summary',aliases='DIPG|H3 K27M glioma')
add('g34','Diffuse hemispheric glioma, H3 G34-mutant','CNS','G34 goes with hemispheres, TP53 and ATRX.','Defining — H3-3A (H3F3A) G34R/V mutation|Cooperating — TP53 and ATRX loss; PDGFRA activating mutation','Cooperating — PDGFRA amplification; CDKN2A/B deletion (subsets)',pitfall='This is a distinct pediatric-type high-grade glioma, including cases in adults; histone legacy G34 numbering is used.',refs='g34')
add('pedhgg','Diffuse pediatric-type high-grade glioma, H3-wildtype and IDH-wildtype','CNS','Pediatric H3/IDH-wildtype high-grade tumors need a positive molecular identity.','Cooperating — TP53 or other pathway mutations (variable)','Driver — PDGFRA, EGFR or MYCN amplification in associated molecular groups',other='Defining context — Appropriate methylation class supports diagnosis; RTK1, RTK2 and MYCN-associated groups exist.',pitfall='H3-wildtype plus IDH-wildtype alone is insufficient; this is not simply childhood glioblastoma.',refs='cns_summary')
add('infant','Infant-type hemispheric glioma','CNS','Infant hemispheric glioma: look for a kinase fusion.',rearr='Driver — ALK, NTRK1/2/3, ROS1 or MET fusion (alternative subsets)',pitfall='Fusion partner varies; absence of a detectable kinase fusion does not by itself exclude the integrated entity.',refs='infant')
add('hgap','High-grade astrocytoma with piloid features','CNS','MAPK activation + CDKN2A/B loss + a defining methylation profile.','Driver — NF1, BRAF or FGFR1 pathway mutation (alternative subsets)|Cooperating — ATRX mutation','Cooperating — CDKN2A/B homozygous deletion','Driver — BRAF or other MAPK-pathway fusion (subset)','Defining — DNA methylation profile is essential to this entity.',pitfall='Piloid morphology or a MAPK mutation alone does not establish HGAP.',refs='hgap',aliases='HGAP')
add('pxa','Pleomorphic xanthoastrocytoma','CNS','PXA pairs BRAF/RAF activation with CDKN2A/B loss.','Driver — BRAF V600E (common subset)|Cooperating — TERT promoter mutation (especially higher-grade tumors)','Cooperating — CDKN2A/B homozygous deletion','Driver — BRAF or RAF1 fusion/rearrangement (alternative subset)',pitfall='Includes grades 2 and 3; grade 2 does not mean a benign tumor. Molecular findings overlap with other gliomas.',refs='pxa',aliases='PXA|Anaplastic PXA')
add('astroblast','Astroblastoma, MN1-altered','CNS','Astroblastoma: MN1 rearrangement.',rearr='Defining — MN1 rearrangement, usually MN1::BEND2; MN1::CXXC5 in a subset',other='Classification — DNA methylation helps resolve histologic mimics.',pitfall='Astroblastic architecture is not specific; molecular identity matters. A uniform CNS WHO grade is not assigned.',refs='pnet',aliases='Astroblastoma')
add('dlgnt','Diffuse leptomeningeal glioneuronal tumor','CNS','MAPK fusion + 1p loss, without IDH mutation.',cnv='Characteristic — 1p loss; 1q gain marks an important molecular subset',rearr='Driver — KIAA1549::BRAF (common); other MAPK-pathway fusions in subsets',other='Classification — Distinct methylation groups; malignant behavior coding does not imply uniformly high-grade histology.',pitfall='Some tumors initially lack diffuse leptomeningeal spread. Do not call this oligodendroglioma from 1p loss alone.',refs='dlgnt|seer_dlgnt',aliases='DLGNT')
add('epn','Ependymoma','CNS','Supratentorial fusions; posterior fossa epigenetics; spinal NF2/MYCN.','Driver — NF2 loss-of-function (spinal subset)','Defining — MYCN amplification in spinal ependymoma, MYCN-amplified|Characteristic — 22q loss in spinal tumors; 1q gain in subsets','Defining — ZFTA::RELA or other ZFTA fusion; YAP1::MAMLD1 or other YAP1 fusion (separate supratentorial types)','Defining — Posterior fossa PFA/PFB methylation groups; PFA commonly shows EZHIP-associated H3K27me3 loss.',pitfall='These alterations describe alternative WHO entities within the broad family, not one co-occurring panel. Subependymoma is excluded.',refs='epn|epn_update',aliases='Supratentorial ependymoma|Posterior fossa ependymoma|Spinal ependymoma|ZFTA|PFA|PFB')
add('cpc','Choroid plexus carcinoma','CNS','Choroid plexus carcinoma: remember TP53.','Driver — TP53 inactivation (somatic or germline-associated subset)','Characteristic — Complex chromosome gains and losses',pitfall='TP53-wildtype cases occur; a tumor TP53 variant alone does not prove a germline syndrome.',refs='cpc')
add('mb','Medulloblastoma','CNS','WNT→CTNNB1; SHH→PTCH1/SMO/SUFU; group 3/4→MYC-family and chromatin.','Driver — CTNNB1 activation or APC loss (WNT)|Driver — PTCH1, SUFU or SMO mutation (SHH); TP53 defines a key SHH subset|Driver/cooperating — KBTBD4 insertions and chromatin-regulator mutations (non-WNT/non-SHH subsets)','Characteristic — Monosomy 6 (WNT subset)|Driver — MYC amplification (group 3 enriched); MYCN or CDK6 amplification (subsets)|Characteristic — Isochromosome 17q (non-WNT/non-SHH enriched)','Driver — Enhancer-hijacking rearrangements involving GFI1/GFI1B or PRDM6 (subsets)','Defining — Molecular groups are integrated with methylation/expression findings.',pitfall='No single mutation covers every medulloblastoma; group names are not interchangeable with histologic patterns.',refs='mb')
add('atrt','Atypical teratoid/rhabdoid tumor','CNS','ATRT = SWI/SNF loss, usually SMARCB1.','Defining — Biallelic SMARCB1 inactivation; rare SMARCA4-inactivated tumors','Defining — SMARCB1 deletion is a common inactivation mechanism','Defining — Structural disruption of SMARCB1 (subset)','Classification — Epigenetic groups exist despite few additional recurrent mutations.',pitfall='Loss of INI1/SMARCB1 protein is a clue, not itself a DNA deletion result; other tumor types also lose SMARCB1.',refs='atrt|smarcb1|cns_summary',aliases='ATRT|AT/RT')
add('etmr','Embryonal tumor with multilayered rosettes','CNS','ETMR: microRNA machinery—C19MC or DICER1.','Driver — DICER1 alterations in a subset without C19MC amplification','Driver — C19MC microRNA-cluster amplification; MIR17HG amplification in rare alternative cases','Driver — C19MC-region rearrangement, including TTYH1::C19MC-associated events',pitfall='C19MC amplification is not universal. Historical CNS medulloepithelioma/ependymoblastoma patterns overlap this family.',refs='etmr',aliases='ETMR')
add('foxr2','CNS neuroblastoma, FOXR2-activated','CNS','CNS FOXR2 is different from peripheral ALK/MYCN neuroblastoma.',cnv='Characteristic — Chromosome 1q gain',rearr='Driver — Structural events activating FOXR2 (variable architecture)',other='Defining — FOXR2 activation with an appropriate methylation profile.',pitfall='FOXR2 expression/activation is the key; a single fixed fusion partner is not required.',refs='pnet',aliases='CNS NB-FOXR2')
add('bcorcns','CNS tumor with BCOR internal tandem duplication','CNS','CNS BCOR tumor: exon 15 internal tandem duplication.','Defining — BCOR exon 15 internal tandem duplication (ITD)',pitfall='BCOR immunostaining alone does not prove an ITD; BCOR fusions in other sarcomas are different alterations.',refs='pnet',aliases='CNS BCOR-ITD')
add('embnos','CNS embryonal tumor, NOS/NEC','CNS','Unresolved embryonal category: no universal genetic driver.',other='Unresolved — Molecular workup has not assigned a recognized specific embryonal entity.',pitfall='NOS reflects missing/insufficient classification information; NEC reflects an investigated tumor outside established entities. Not one molecular disease.',refs='cns_summary',aliases='CNS-PNET')
add('pineoblast','Pineoblastoma','CNS','Pineoblastoma: microRNA processing, RB1, or MYC/FOXR2.','Driver — DICER1, DROSHA or DGCR8 defects (miRNA-associated groups)|Driver — RB1 inactivation (RB-associated group)','Driver — DROSHA/DGCR8 or RB1 loss; MYC amplification (group-dependent)',other='Classification — MYC/FOXR2 activation and distinct methylation groups are important.',pitfall='Listed abnormalities belong to alternative groups; not every pineoblastoma is DICER1-mutant.',refs='pb')
add('pptid','Pineal parenchymal tumor of intermediate differentiation','CNS','PPTID: KBTBD4 insertion.','Driver — Recurrent small in-frame KBTBD4 insertion (subset)',pitfall='“Intermediate differentiation” is the entity name, not synonymous with benign/intermediate behavior. No single mutation fully grades it.',refs='pptid',aliases='PPTID')
add('ptpr','Papillary tumor of the pineal region','CNS','Papillary pineal tumor: chromosome 10 loss; PTEN in a subset.','Driver — PTEN inactivation (subset)','Characteristic — Chromosome 10 loss',other='Classification — Distinct DNA methylation profile.',pitfall='PTEN mutations are variable across cohorts; chromosome 10 loss is not uniquely diagnostic.',refs='ptpr',aliases='PTPR')
add('mening','Meningioma, CNS WHO grade 3','CNS','Grade 3 molecular flags: TERT promoter or CDKN2A/B homozygous loss.','Grading — TERT promoter mutation|Driver/cooperating — NF2 or BAP1 inactivation (subsets)','Grading — CDKN2A and/or CDKN2B homozygous deletion|Characteristic — Accumulated chromosomal losses in aggressive tumors',pitfall='Only grade 3 is included here. Grade 3 can be assigned by histology or qualifying molecular findings; rhabdoid morphology alone is insufficient.',refs='mening|cns_summary',aliases='Anaplastic meningioma|Malignant meningioma')
add('cnsdicer','Primary intracranial sarcoma, DICER1-mutant','CNS','Intracranial sarcoma: DICER1 plus MAPK/TP53.','Defining — DICER1 RNase IIIb hotspot mutation, often with second-allele inactivation|Cooperating — TP53; KRAS or NF1 pathway alterations (subsets)',pitfall='A DICER1 alteration must be interpreted with histology/site and methylation classification; tumor-only findings do not establish germline status.',refs='cns_dicer')

add('lipo','Liposarcoma','Soft tissue and bone','Three routes: MDM2 amplification, DDIT3 fusion, or complex TP53/RB1 damage.','Cooperating — TP53 and ATRX alterations (pleomorphic/myxoid pleomorphic subsets)|Cooperating — TERT promoter and PIK3CA alterations (myxoid subset)','Defining — MDM2 amplification, often with CDK4 (well-differentiated/dedifferentiated)|Cooperating — RB1 loss (pleomorphic/myxoid pleomorphic subsets)','Defining — FUS::DDIT3 or EWSR1::DDIT3 (myxoid)',pitfall='Keep the molecular subsets separate in memory. Atypical lipomatous tumor is an intermediate counterpart and is outside the malignant-only scope.',refs='tcga_sarc|lipo',aliases='Dedifferentiated liposarcoma|Myxoid liposarcoma|Pleomorphic liposarcoma|Myxoid pleomorphic liposarcoma|Well-differentiated liposarcoma')
add('lms','Leiomyosarcoma','Soft tissue and bone','Smooth muscle sarcoma: TP53, RB1, ATRX; complex genome.','Driver/cooperating — TP53, RB1, ATRX and PTEN inactivation (subsets)','Cooperating — RB1/PTEN loss; MYOCD amplification (subset)',pitfall='No universal defining fusion. Covers soft tissue, uterine and primary bone sites; the inflammatory subtype has distinctive near-haploid genomes.',refs='tcga_sarc',aliases='Uterine leiomyosarcoma|Leiomyosarcoma of bone|Inflammatory leiomyosarcoma')
add('rms','Rhabdomyosarcoma','Soft tissue and bone','RMS: FOXO1 fusion, RAS pathway, or MYOD1.','Driver — HRAS/KRAS/NRAS, FGFR4 or PIK3CA activation (fusion-negative subsets)|Driver — MYOD1 L122R (spindle/sclerosing subset)|Cooperating — TP53; DICER1 in selected anatomic subsets','Cooperating — 11p15 allelic imbalance; MYCN/CDK4 amplification (subsets)','Defining — PAX3::FOXO1 or PAX7::FOXO1 (fusion-positive subset)|Driver — VGLL2/NCOA2-associated fusions in infantile spindle-cell tumors; TFCP2 fusions in a rare intraosseous subset',pitfall='Broad family includes embryonal, alveolar, pleomorphic and spindle/sclerosing tumors. Histologic alveolar appearance is not equivalent to FOXO1 fusion.',refs='rms',aliases='Embryonal rhabdomyosarcoma|Alveolar rhabdomyosarcoma|Pleomorphic rhabdomyosarcoma|Spindle cell sclerosing rhabdomyosarcoma')
add('sft','Solitary fibrous tumor, malignant/high-risk','Soft tissue and bone','Solitary fibrous tumor: NAB2::STAT6.',rearr='Defining — NAB2::STAT6',pitfall='The fusion identifies the tumor family, not malignant behavior; risk assessment remains clinicopathologic. Includes malignant CNS SFT.',refs='sft',aliases='Hemangiopericytoma|Malignant solitary fibrous tumor')
add('fibro','Adult-type fibrosarcoma / fibrosarcoma of bone','Soft tissue and bone','A diagnosis of exclusion; no universal molecular hallmark.',other='Unresolved — No established recurrent defining driver for conventional adult-type fibrosarcoma.',pitfall='Exclude fusion-defined mimics and other differentiated sarcomas before using this diagnosis.',refs='sarc_seq',aliases='Adult fibrosarcoma|Fibrosarcoma of bone')
add('lowmyofib','Low-grade myofibroblastic sarcoma','Soft tissue and bone','Myofibroblastic morphology; no established signature driver.',other='Unresolved — No established recurrent defining molecular alteration.',pitfall='Do not transfer ALK fusions from inflammatory myofibroblastic tumor to this different entity.',refs='sarc_seq')
add('mfs','Myxofibrosarcoma','Soft tissue and bone','Complex genome: TP53/RB1/CDKN2A pathways.','Driver/cooperating — TP53 and other tumor-suppressor mutations','Cooperating — RB1, CDKN2A/B or TP53 loss; complex gains/losses',pitfall='No single pathognomonic fusion; overlaps genomically with undifferentiated pleomorphic sarcoma.',refs='tcga_sarc')
add('lgfms','Low-grade fibromyxoid sarcoma','Soft tissue and bone','Fibromyxoid + FUS::CREB3L2.',rearr='Defining — FUS::CREB3L2; FUS::CREB3L1 in a smaller subset',pitfall='Bland histology does not imply benign behavior; hybrid LGFMS/SEF can share the FUS-associated profile.',refs='sef',aliases='LGFMS|Hyalinizing spindle cell tumor with giant rosettes')
add('sef','Sclerosing epithelioid fibrosarcoma','Soft tissue and bone','Sclerosing epithelioid sarcoma: EWSR1::CREB3L1.',rearr='Defining — EWSR1::CREB3L1 (common); EWSR1::CREB3L2 (subset)|Defining — FUS::CREB3L2 in some hybrid LGFMS/SEF tumors',pitfall='MUC4 expression is an immunophenotypic clue, not a mutation; pure SEF and LGFMS have different fusion enrichments.',refs='sef',aliases='SEF')
add('ifs','Infantile fibrosarcoma','Soft tissue and bone','Infantile fibrosarcoma: ETV6::NTRK3.',rearr='Defining — ETV6::NTRK3 (typical)|Driver — Alternative NTRK or other kinase fusions in related fusion-negative tumors',pitfall='ETV6::NTRK3 is shared by several other entities; age, site and histology remain necessary.',refs='ifs|ntrk3',aliases='Congenital fibrosarcoma')
